/* ----------------------------- time ------------------------------- */

export const DAYS = 30; // one-month observation window
export const MONTH_LABEL = "January 2026";

function pad(n: number) {
  return n < 10 ? `0${n}` : `${n}`;
}
export function isoDate(day: number): string {
  return `2026-01-${pad(Math.min(Math.max(day, 1), 30))}`;
}
export function shortDate(day: number): string {
  return `${pad(Math.min(Math.max(day, 1), 30))} Jan`;
}

/* ----------------------- deterministic PRNG ------------------------ */

export function hashStr(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
/** Symmetric pseudo-random noise in [-spread, spread], stable per key. */
export function noise(key: string, spread = 1): number {
  return (mulberry32(hashStr(key))() * 2 - 1) * spread;
}

function gauss(lon: number, lat: number, cLon: number, cLat: number, sLon: number, sLat: number): number {
  const dx = (lon - cLon) / sLon;
  const dy = (lat - cLat) / sLat;
  return Math.exp(-(dx * dx + dy * dy));
}
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

