/** Point-in-polygon (ray casting) on lon/lat space. */
export function inPolygon(lon: number, lat: number, poly: [number, number][]): boolean {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i];
    const [xj, yj] = poly[j];
    const intersect =
      yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

export function isLand(lon: number, lat: number): boolean {
  if (inPolygon(lon, lat, MAINLAND)) return true;
  if (inPolygon(lon, lat, SRI_LANKA)) return true;
  if (inPolygon(lon, lat, SUMATRA)) return true;
  for (const [cx, cy, rx, ry] of ANDAMANS) {
    const dx = (lon - cx) / rx;
    const dy = (lat - cy) / ry;
    if (dx * dx + dy * dy < 1) return true;
  }
  for (const [ax, ay] of ATOLLS) {
    if (Math.abs(lon - ax) < 0.1 && Math.abs(lat - ay) < 0.1) return true;
  }
  return false;
}

