/* ---------------------- physical field model ----------------------- */

function tempAtDepth(depth: number): number {
  const pts: [number, number][] = [[0, 28.7], [50, 26.2], [100, 20.0], [200, 14.4]];
  if (depth <= 0) return pts[0][1];
  for (let i = 1; i < pts.length; i++) {
    if (depth <= pts[i][0]) {
      const [d0, v0] = pts[i - 1];
      const [d1, v1] = pts[i];
      return v0 + ((v1 - v0) * (depth - d0)) / (d1 - d0);
    }
  }
  return pts[pts.length - 1][1];
}

/** Smooth "truth" field of the selected variable at lon/lat/depth. */
export function fieldValue(variable: VariableKey, lon: number, lat: number, depth: number, day = 15): number {
  if (variable === "temperature") {
    const fall = clamp(depth / 200, 0, 1);
    let t = tempAtDepth(depth);
    t += (-0.045 * (lat - 8) + 0.02 * (lon - 84)) * (1 - 0.6 * fall);
    t += 1.15 * gauss(lon, lat, 84.5, 7.5, 7, 4.5) * (1 - fall);
    t -= 0.85 * gauss(lon, lat, 80.4, 12.0, 2.5, 7) * (1 - fall); // TN upwelling
    t += 0.55 * gauss(lon, lat, 94.5, 10.5, 4, 5) * (1 - 0.5 * fall);
    t += Math.sin(day / 5.1) * 0.35 * (1 - fall) + day * 0.016;
    return clamp(t, 4, 31.5);
  }
  if (variable === "salinity") {
    const fall = clamp(depth / 250, 0, 1);
    let s = 33.05 + depth * 0.0011;
    s += 1.55 * gauss(lon, lat, 65.5, 17, 10, 9);
    s -= 2.1 * gauss(lon, lat, 89.5, 20.5, 7.5, 5) * (1 - fall); // northern river plume
    s -= 0.55 * gauss(lon, lat, 80.9, 12.5, 3, 5) * (1 - fall);
    s += 0.3 * gauss(lon, lat, 94, 8, 5, 6);
    s += Math.sin(day / 6.3 + 1.2) * 0.07 * (1 - fall);
    return clamp(s, 29.6, 36.6);
  }
  // current speed
  let c = 0.16;
  c += 0.85 * gauss(lon, lat, 87.6, 15.0, 6, 5.5);
  c += 0.7 * gauss(lon, lat, 71.5, 8.2, 5.5, 4.5);
  c += 0.42 * gauss(lon, lat, 93.0, 7.2, 3, 3);
  c += 0.12 * Math.abs(Math.sin(lon * 0.35 + day * 0.1) * Math.cos(lat * 0.3));
  c *= 1 - clamp(depth / 350, 0, 0.75);
  return clamp(c, 0.05, 1.5);
}

/** Direction (degrees, clockwise from North) for current arrows. */
export function currentDirection(lon: number, lat: number, day = 15): number {
  const gyre = (cLon: number, cLat: number, strength: number, clockwise: boolean) => {
    const dx = lon - cLon;
    const dy = lat - cLat;
    const r = Math.hypot(dx, dy) + 0.001;
    const w = strength * Math.exp(-r / 7);
    // tangent angle (radians) around gyre centre
    const ang = Math.atan2(dx, dy) + (clockwise ? Math.PI / 2 : -Math.PI / 2);
    return { w, ang };
  };
  const g1 = gyre(87.6, 15.0, 1.4, false);
  const g2 = gyre(71.5, 8.2, 1.1, true);
  const g3 = gyre(93.0, 7.2, 0.8, false);
  // background west-bound equatorial flow + along-coast drift
  let x = Math.sin((215 * Math.PI) / 180) * 0.25;
  let y = Math.cos((215 * Math.PI) / 180) * 0.25;
  for (const g of [g1, g2, g3]) {
    x += Math.sin(g.ang) * g.w;
    y += Math.cos(g.ang) * g.w;
  }
  const deg = (Math.atan2(x, y) * 180) / Math.PI + noise(`dir|${lon.toFixed(1)}|${lat.toFixed(1)}|${day}`, 12);
  return (deg + 360) % 360;
}

/* --------------- observed vs model value generation ---------------- */

const HIGH_DEV_STATIONS = new Set(["BUOY-BOB-08", "SHIP-IO-233"]);

function biasFor(stationId: string, variable: VariableKey, depth: number): number {
  const depthScale = 1 + depth / 90;
  const base = noise(`${stationId}|${variable}|bias`, 1);
  const flagged = HIGH_DEV_STATIONS.has(stationId) ? Math.sign(base || 1) * 0.62 : 0;
  switch (variable) {
    case "temperature":
      return base * 0.62 * (1 + depth / 150) + flagged * (1.05 + depth / 150) + 0.04;
    case "salinity":
      return base * 0.18 * depthScale + flagged * 0.26 - 0.05;
    case "current":
      return base * 0.11 * depthScale + flagged * 0.15 - 0.02;
  }
}

export function observedValue(station: Station, variable: VariableKey, depth: number, day: number): number {
  const f = fieldValue(variable, station.lon, station.lat, depth, day);
  const amp = variable === "temperature" ? 0.22 : variable === "salinity" ? 0.1 : 0.1;
  const n = noise(`${station.id}|${variable}|${depth}|${day}|obs`, amp);
  return f + n;
}

export function modelValue(station: Station, variable: VariableKey, depth: number, day: number): number {
  // The model is a *smoothed* version of the truth plus a persistent bias:
  const lon = station.lon + 0.35; // grid-cell offset mimics coarse resolution
  const lat = station.lat - 0.28;
  const f = fieldValue(variable, lon, lat, depth, day);
  const smoothNoise = noise(`${station.id}|${variable}|${depth}|${Math.floor(day / 3)}|mdl`, variable === "temperature" ? 0.12 : 0.06);
  return f + biasFor(station.id, variable, depth) + smoothNoise;
}

export function statusFor(variable: VariableKey, diff: number): StatusLevel {
  const def = variableByKey(variable);
  const a = Math.abs(diff);
  if (a < def.goodBelow) return "good";
  if (a < def.moderateBelow) return "moderate";
  return "high";
}

export const STATUS_META: Record<StatusLevel, { label: string; short: string; color: string; bg: string; text: string; border: string }> = {
  good: { label: "Good Agreement", short: "Good", color: "#15803D", bg: "bg-emerald-50", text: "text-emerald-700", border: "border-emerald-200" },
  moderate: { label: "Moderate Agreement", short: "Moderate", color: "#B45309", bg: "bg-amber-50", text: "text-amber-700", border: "border-amber-200" },
  high: { label: "High Deviation", short: "Deviation", color: "#B91C1C", bg: "bg-red-50", text: "text-red-700", border: "border-red-200" },
};

/* ------------------- series & aggregate computations --------------- */

export interface FilterSpec {
  region: RegionKey;
  variable: VariableKey;
  depth: Depth;
  fromDay: number;
  toDay: number;
}

export function stationSeries(station: Station, variable: VariableKey, depth: number, fromDay = 1, toDay = DAYS): SeriesPoint[] {
  const out: SeriesPoint[] = [];
  for (let d = fromDay; d <= toDay; d++) {
    const obs = observedValue(station, variable, depth, d);
    const mdl = modelValue(station, variable, depth, d);
    out.push({ date: shortDate(d), day: d, observed: +obs.toFixed(3), model: +mdl.toFixed(3), diff: +(mdl - obs).toFixed(3) });
  }
  return out;
}

/** Regional mean time series (average of all stations inside the region). */
export function regionSeries(spec: FilterSpec): SeriesPoint[] {
  const stations = stationsInRegion(spec.region).filter((s) => s.depths.includes(spec.depth));
  const out: SeriesPoint[] = [];
  for (let d = spec.fromDay; d <= spec.toDay; d++) {
    let o = 0, m = 0;
    for (const s of stations) {
      o += observedValue(s, spec.variable, spec.depth, d);
      m += modelValue(s, spec.variable, spec.depth, d);
    }
    const n = stations.length || 1;
    out.push({ date: shortDate(d), day: d, observed: +(o / n).toFixed(3), model: +(m / n).toFixed(3), diff: +((m - o) / n).toFixed(3) });
  }
  return out;
}

export function scatterData(spec: FilterSpec): ScatterPoint[] {
  const stations = stationsInRegion(spec.region).filter((s) => s.depths.includes(spec.depth));
  const out: ScatterPoint[] = [];
  for (const s of stations) {
    for (let d = spec.fromDay; d <= spec.toDay; d += 2) {
      const obs = +observedValue(s, spec.variable, spec.depth, d).toFixed(3);
      const mdl = +modelValue(s, spec.variable, spec.depth, d).toFixed(3);
      out.push({ id: `${s.id}-${d}`, stationId: s.id, model: mdl, observed: obs, status: statusFor(spec.variable, mdl - obs) });
    }
  }
  return out;
}

export function matchRecords(spec: FilterSpec): MatchRecord[] {
  const stations = stationsInRegion(spec.region).filter((s) => s.depths.includes(spec.depth));
  const out: MatchRecord[] = [];
  for (const s of stations) {
    for (let d = spec.fromDay; d <= spec.toDay; d += 2) {
      const obs = observedValue(s, spec.variable, spec.depth, d);
      const mdl = modelValue(s, spec.variable, spec.depth, d);
      const diff = mdl - obs;
      out.push({
        stationId: s.id,
        platform: s.platform,
        date: shortDate(d),
        lat: s.lat,
        lon: s.lon,
        depth: spec.depth,
        model: +mdl.toFixed(3),
        observed: +obs.toFixed(3),
        diff: +diff.toFixed(3),
        status: statusFor(spec.variable, diff),
      });
    }
  }
  return out;
}

export function validationMetrics(spec: FilterSpec): { mae: number; rmse: number; bias: number; n: number } {
  const recs = matchRecords(spec);
  if (!recs.length) return { mae: 0, rmse: 0, bias: 0, n: 0 };
  let sa = 0, ss = 0, sb = 0;
  for (const r of recs) {
    sa += Math.abs(r.diff);
    ss += r.diff * r.diff;
    sb += r.diff;
  }
  const n = recs.length;
  return { mae: sa / n, rmse: Math.sqrt(ss / n), bias: sb / n, n };
}

/** Deterministic data coverage %, slightly lower at deeper levels. */
export function coverageFor(spec: FilterSpec): number {
  const regionPenalty: Record<RegionKey, number> = { bob: 5.1, arabian: 6.2, indian: 7.4, tn: 9.8, andaman: 8.6 };
  const varPenalty = spec.variable === "current" ? 2.6 : spec.variable === "salinity" ? 1.2 : 0;
  const v = 97.5 - regionPenalty[spec.region] - spec.depth * 0.02 - varPenalty;
  return clamp(v, 80, 98.5);
}

export function depthAgreement(spec: FilterSpec): DepthAgreement[] {
  const depths: Depth[] = [0, 50, 100, 200];
  return depths.map((depth) => {
    const stations = stationsInRegion(spec.region).filter((s) => s.depths.includes(depth));
    let n = 0, sa = 0, sb = 0;
    for (const s of stations) {
      for (let d = spec.fromDay; d <= spec.toDay; d += 3) {
        const diff = modelValue(s, spec.variable, depth, d) - observedValue(s, spec.variable, depth, d);
        sa += Math.abs(diff);
        sb += diff;
        n++;
      }
    }
    return { depth, mae: n ? +(sa / n).toFixed(3) : 0, bias: n ? +(sb / n).toFixed(3) : 0, n };
  }).filter((d) => d.n > 0);
}

export function errorHistogram(spec: FilterSpec): ErrorBin[] {
  const def = variableByKey(spec.variable);
  const edges = [0, def.goodBelow, def.moderateBelow, def.moderateBelow * 1.8, Infinity];
  const labels = [
    `0 – ${def.goodBelow}`,
    `${def.goodBelow} – ${def.moderateBelow}`,
    `${def.moderateBelow} – ${(def.moderateBelow * 1.8).toFixed(1)}`,
    `> ${(def.moderateBelow * 1.8).toFixed(1)}`,
  ];
  const counts = [0, 0, 0, 0];
  for (const r of matchRecords(spec)) {
    const a = Math.abs(r.diff);
    for (let i = 0; i < 4; i++) {
      if (a >= edges[i] && a < edges[i + 1]) {
        counts[i]++;
        break;
      }
    }
  }
  return labels.map((range, i) => ({ range: `${range} ${def.unit}`, count: counts[i] }));
}

/** Mean |error| on a coarse lon/lat grid — used by the error heatmap. */
export function errorGrid(spec: FilterSpec, step = 2): ErrorCell[] {
  const region = regionByKey(spec.region);
  const cells: ErrorCell[] = [];
  const stations = stationsInRegion(spec.region).filter((s) => s.depths.includes(spec.depth));
  for (let lon = region.bbox.lonMin + step / 2; lon < region.bbox.lonMax; lon += step) {
    for (let lat = region.bbox.latMin + step / 2; lat < region.bbox.latMax; lat += step) {
      if (isLand(lon, lat)) continue;
      // blend of distance to nearest stations: nearby stations anchor the error field
      let best = Infinity;
      let err = 0;
      for (const s of stations) {
        const dist = Math.hypot(s.lon - lon, s.lat - lat);
        if (dist < best) {
          best = dist;
          err = Math.abs(
            noise(`${s.id}|${spec.variable}|${spec.depth}|bias`, 1) *
              (spec.variable === "temperature" ? 0.42 : spec.variable === "salinity" ? 0.2 : 0.11) *
              (1 + spec.depth / 120) +
              (HIGH_DEV_STATIONS.has(s.id) ? 0.5 * (spec.variable === "salinity" ? 0.4 : 1) : 0)
          );
        }
      }
      const falloff = clamp(1.35 - best / 9, 0.25, 1.1);
      cells.push({ lon, lat, error: +(err * falloff).toFixed(3) });
    }
  }
  return cells;
}

/** Plain-language interpretation, generated with simple rules (no AI). */
export function interpretationFor(spec: FilterSpec): string[] {
  const depths = depthAgreement(spec);
  const metrics = validationMetrics(spec);
  const def = variableByKey(spec.variable);
  const region = regionByKey(spec.region);
  if (!depths.length) return ["No matched records available for the current filters."];
  const best = depths.reduce((a, b) => (a.mae <= b.mae ? a : b));
  const worst = depths.reduce((a, b) => (a.mae >= b.mae ? a : b));
  const out: string[] = [];
  const depthName = (d: number) => (d === 0 ? "the surface (0 m)" : `${d} m depth`);
  if (best.depth === worst.depth) {
    out.push(`Model agreement is consistent across the sampled depth layers in the selected ${region.label} region.`);
  } else {
    out.push(
      `Model performance is strongest at ${depthName(best.depth)} (MAE ${best.mae.toFixed(2)} ${def.unit}) and weakest at ${depthName(worst.depth)} (MAE ${worst.mae.toFixed(2)} ${def.unit}) in the selected ${region.label} region.`
    );
  }
  if (metrics.bias < -0.05) {
    out.push(`The model shows a cool/low bias of ${metrics.bias.toFixed(2)} ${def.unit}: predicted values are on average lower than the measurements.`);
  } else if (metrics.bias > 0.05) {
    out.push(`The model shows a warm/high bias of +${metrics.bias.toFixed(2)} ${def.unit}: predicted values are on average higher than the measurements.`);
  } else {
    out.push("Mean bias is close to zero: model and observations agree well on average.");
  }
  if (worst.depth >= 100) {
    out.push("Larger deviations below the thermocline may reflect unresolved subsurface mixing in the model's vertical scheme.");
  }
  return out;
}

/** Narrative for a single station snapshot. */
export function snapshotNarrative(variable: VariableKey, diff: number, depth: number): string {
  const def = variableByKey(variable);
  const a = Math.abs(diff);
  const depthText = depth === 0 ? "near the surface" : `at ${depth} m depth`;
  if (a < def.goodBelow) {
    return `Model and observation differ by only ${a.toFixed(2)} ${def.unit} ${depthText} — the model reproduces conditions here reliably.`;
  }
  const direction = diff < 0 ? "underestimates" : "overestimates";
  const what = variable === "temperature" ? "the observed temperature" : variable === "salinity" ? "the observed salinity" : "the observed current speed";
  return `The model ${direction} ${what} by ${a.toFixed(2)} ${def.unit} at this location ${depthText}.`;
}
